//! Display metadata from the same package-bound declarations used by agent tools.
//! A declaration is not a successful qualification or a package admission verdict.
use serde_json::{json, Value};
use std::sync::OnceLock;

/// Every checked-in declaration (source bytes and parsed value), generated by build.rs from
/// apps/interfaces: the one list both the gallery and the typed-tool summary read.
pub(super) fn declarations() -> &'static [(&'static str, Value)] {
    static DECLARATIONS: OnceLock<Vec<(&'static str, Value)>> = OnceLock::new();
    DECLARATIONS.get_or_init(|| {
        let sources: &[&str] = include!(concat!(env!("OUT_DIR"), "/app-interface-sources.rs"));
        sources.iter().filter_map(|s| {
            let value: Value = serde_json::from_str(s).ok()?;
            (value["format"] == "mini-app-interface-v1").then_some((*s, value))
        }).collect()
    })
}

pub(super) fn summary(app_id: &str, package_id: &str) -> Value {
    let Some((_, d)) = declarations().iter().find(|(_, d)| d["appId"] == app_id && d["packageId"] == package_id) else {
        return Value::Null;
    };
    json!({"version":d["interfaceVersion"], "status":d["status"], "$defs":d["$defs"], "operations":d["operations"]
        .as_object().into_iter().flatten().filter(|(_, op)| op["internal"] != true).map(|(name, op)| json!({
            "name":name,"description":op["description"],"input":op["input"],
            "output":op["output"],"write":op["write"]
        })).collect::<Vec<_>>()})
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn operations_are_package_bound_and_keep_the_declared_status() {
        assert!(!declarations().is_empty());
        for (_, d) in declarations() {
            let app = d["appId"].as_str().unwrap();
            let package = d["packageId"].as_str().unwrap();
            let found = summary(app, package);
            assert_eq!(found["status"], d["status"]);
            let public = d["operations"].as_object().unwrap().values().filter(|op| op["internal"] != true).count();
            assert_eq!(found["operations"].as_array().unwrap().len(), public, "internal operations are never advertised");
            assert!(summary(app, "another-package").is_null());
            assert!(summary("another-app", package).is_null());
        }
    }
}
